import type { VariableConfig } from '../../Variable';
import type { Record } from '../../../db/Record';
import type { TableName } from '../../../db/Table';
/**
 * Common base type for lookup variables (LookupMultipleChoice, LookupSelectBox)
 */
export type LookupVariableBaseType<RefTable extends TableName = TableName, Type extends Record<RefTable> | Now.Internal.ExplicitKey | string = Record<RefTable> | Now.Internal.ExplicitKey | string> = VariableConfig<Type> & {
    choiceDirection?: 'down' | 'across';
    includeNone?: boolean;
    referenceQual?: string;
    /** Unique values only (price fields not allowed when true) */
    uniqueValuesOnly?: boolean;
    /** Lookup from a table. Mutually exclusive with lookupSource='choices'. */
    lookupFromTable?: RefTable;
    lookupValueField?: string;
    lookupLabelFields?: string[];
    /** Price fields (not allowed when uniqueValuesOnly is true) */
    lookupPriceField?: string;
    lookupRecurringPriceField?: string;
    /** Lookup from choices. Mutually exclusive with lookupFromTable. */
    lookupSource?: 'choices';
    choiceTable?: RefTable;
    choiceField?: string;
    choicesDependOn?: string;
};
